def transition_value(theta: tf.Tensor, particles: tf.Tensor, noise: tf.Tensor, _time: tf.Tensor) -> tf.Tensor:
    phi, q_scale, _ = physical(theta)
    return particles * phi[None, :] + q_scale * noise
